type Uint is uint;


function unaryCountdown(Uint x) pure returns (Uint) {
    if (eq(x, Uint.wrap(0)))
        return Uint.wrap(0);

    return unaryCountdown(Uint.wrap(Uint.unwrap(x) - 1));
}

function binaryCountdown(Uint x, Uint y) pure returns (Uint) {
    if (eq(x, Uint.wrap(0)) && eq(y, Uint.wrap(0)))
        return Uint.wrap(0);
    if (eq(x, Uint.wrap(0)))
        return binaryCountdown(y, x);

    return binaryCountdown(Uint.wrap(Uint.unwrap(x) - 1), y);
}

function eq(Uint x, Uint y) pure returns (bool) {
    return Uint.unwrap(x) == Uint.unwrap(y);
}

contract C {
    function testUnary(Uint x) public pure returns (Uint) {
        return unaryCountdown(x);
    }

    function testBinary(Uint x, Uint y) public pure returns (Uint) {
        return binaryCountdown(x, y);
    }
}
